// OCR.space returns ParsedResults[0].ParsedText; normalize to .text
const r = $input.first().json;
const text = (r.ParsedResults && r.ParsedResults[0] && r.ParsedResults[0].ParsedText) || r.text || '';
return [{ json: { text }, binary: $input.first().binary }];

// Score the resume against EVERY requirement and return the best-matching one.
const CAL_LO = 0.30, CAL_HI = 0.65;
const MODEL = 'sentence-transformers/all-MiniLM-L6-v2';
const MAX_CHUNKS = 40, MAX_LEN = 400, MAX_REQ_UNITS = 12;
const resumeText = String($input.first().json.text || '');
let reqs = [];
try { reqs = JSON.parse($('Webhook').first().json.body.requirements || '[]'); } catch (e) {}

const clean = (s) => String(s || '').replace(/\s+/g, ' ').trim();
const splitUnits = (t) => String(t || '').split(/[\r\n;•·]+|(?<=[.!?])\s+/).map(clean).filter((u) => u.length >= 8 && u.split(' ').length >= 2).map((u) => u.slice(0, MAX_LEN));
const cos = (a, b) => { let d = 0, na = 0, nb = 0; for (let i = 0; i < a.length; i++) { d += a[i]*b[i]; na += a[i]*a[i]; nb += b[i]*b[i]; } return d / (Math.sqrt(na)*Math.sqrt(nb) || 1); };
const clamp = (x, lo, hi) => Math.min(Math.max(x, lo), hi);

let resumeChunks = [...new Set(splitUnits(resumeText))].slice(0, MAX_CHUNKS);
if (resumeChunks.length === 0) resumeChunks = [resumeText.slice(0, MAX_LEN) || ' '];

const reqUnitLists = reqs.map((r) => {
  let u = [...splitUnits(r.qualifications), ...splitUnits(r.description)];
  if (r.job_title) u.unshift(clean(r.job_title).slice(0, MAX_LEN));
  return [...new Set(u)].slice(0, MAX_REQ_UNITS);
});
const flatReqUnits = [];
const spans = [];
reqUnitLists.forEach((list) => { const s = flatReqUnits.length; list.forEach((x) => flatReqUnits.push(x)); spans.push([s, flatReqUnits.length]); });

let best = { requirement_id: (reqs[0] && reqs[0].requirement_id) || null, score: 0 };
try {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://router.huggingface.co/hf-inference/models/${MODEL}/pipeline/feature-extraction`,
    headers: { Authorization: `Bearer ${$env.HF_API_KEY}`, 'Content-Type': 'application/json' },
    body: { inputs: [...resumeChunks, ...flatReqUnits], options: { wait_for_model: true } },
    json: true,
  });
  const vecs = Array.isArray(resp[0][0]) ? resp.map((s) => { const dim = s[0].length, o = new Array(dim).fill(0); s.forEach((t) => t.forEach((x, i) => o[i] += x)); return o.map((x) => x / s.length); }) : resp;
  const resVecs = vecs.slice(0, resumeChunks.length);
  const reqVecsAll = vecs.slice(resumeChunks.length);
  let bestScore = -1, bestId = best.requirement_id;
  reqs.forEach((r, ri) => {
    const [s, e] = spans[ri];
    const rv = reqVecsAll.slice(s, e);
    if (rv.length === 0) return;
    const coverage = rv.map((v) => Math.max(...resVecs.map((cv) => cos(v, cv))));
    let raw = coverage.reduce((a, b) => a + b, 0) / coverage.length;
    if (CAL_HI > CAL_LO) raw = clamp((raw - CAL_LO) / (CAL_HI - CAL_LO), 0, 1);
    const score = Math.round(clamp(raw * 100, 0, 100) * 100) / 100;
    if (score > bestScore) { bestScore = score; bestId = r.requirement_id; }
  });
  best = { requirement_id: bestId, score: bestScore < 0 ? 0 : bestScore };
} catch (e) {}

return [{ json: { best_requirement_id: best.requirement_id, best_score: best.score } }];
